"""Duration texts of a time sheet, as README.md describes them."""

_DIGITS = "0123456789"
_UNITS = (("h", 3600), ("m", 60), ("s", 1))


def _to_int(digits):
    """The value of a string of ASCII digits, of any length (int() refuses
    very long digit strings, so long ones are split and joined)."""
    if len(digits) <= 1000:
        return int(digits)
    half = len(digits) // 2
    low = digits[-half:]
    return _to_int(digits[:-half]) * 10 ** len(low) + _to_int(low)


def measure_duration(text):
    """The seconds the duration text stands for, as an int; ValueError for
    a string that is not a duration text."""
    if not isinstance(text, str):
        raise ValueError("not a duration text")
    total = 0
    pos = 0
    length = len(text)
    unit_index = 0
    parts = 0
    while pos < length:
        start = pos
        while pos < length and text[pos] in _DIGITS:
            pos += 1
        if pos == start or pos >= length:
            raise ValueError("not a duration text")
        unit = text[pos]
        while unit_index < len(_UNITS) and _UNITS[unit_index][0] != unit:
            unit_index += 1
        if unit_index == len(_UNITS):
            raise ValueError("not a duration text")
        total += _to_int(text[start:pos]) * _UNITS[unit_index][1]
        unit_index += 1
        pos += 1
        parts += 1
    if parts == 0:
        raise ValueError("not a duration text")
    return total
